def density_paragraphs(text: str) -> list[str]:
    """Paragraphs stating a 1x/2x requirement, in either spelling of ×."""

    return [
        paragraph
        for paragraph in re.split(r"\n\s*\n", text)
        if re.search(r"2\s*[x×]", paragraph, re.I)
    ]


def density_rule_triggers(text: str) -> set[str]:
    """Which conditions a file says require evidence at both densities.

    A source whose dimensions changed carries no `srcset` in this repository —
    the header logo, the avatar control, and the contact background are all
    plain `<img>` or a CSS `backgroundImage` — so dropping that half of the
    trigger silently exempts exactly the re-encode the rule was written for.
    """

    triggers: set[str] = set()
    for paragraph in density_paragraphs(text):
        if "srcset" in paragraph:
            triggers.add("srcset")
        if re.search(r"(?i)dimensions", paragraph):
            triggers.add("dimensions")
    return triggers


