def test_a_placeholder_in_a_pasted_command_is_a_syntax_error(self):
    """Why the live check runs bash rather than reading the line.

    The angle-bracket form looks like every other placeholder in these
    documents and is the one that does not survive a shell.
    """

    def parses(line: str) -> bool:
        return (
            subprocess.run(
                ["bash", "-n"], input=line, capture_output=True, text=True
            ).returncode
            == 0
        )

    self.assertFalse(parses("make migrate NAME=<migration-name>\n"))
    self.assertTrue(parses("make migrate NAME=add-order-status\n"))
    self.assertTrue(parses("make migrate-deploy\n"))

